window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-238daf3685100864"]={"versions": [{"id": "FIG-238daf3685100864", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR</code>) zur Spezifikation des Lebenszyklus und der Betriebsmodi des AUTOSAR PDU Routers (PduR) innerhalb der Kommunikationsinfrastruktur der AUTOSAR Classic Platform (Services Layer).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Ruhezustand des Moduls vor erfolgreicher Konfiguration/Initialisierung.\n</li><li><code>PDUR_ONLINE</code>: Regulärer Betriebszustand für Routing- und Vermittlungsfunktionen von PDUs.\n</li><li><code>PDUR_REDUCED</code>: Fehlerzustand bei fehlgeschlagener Initialisierung mit reduzierter bzw. eingeschränkter Funktionalität.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li><li>Endzustand (Final State): Kreis mit Diagonalkreuz (<code>PowerDown</code>).\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Ereignislose, unmittelbare Transition nach Systemstart.\n</li><li><code>PduR_Init(ConfigPtr)</code>: Initialisierungsaufruf mit Konfigurationszeiger; verzweigt je nach Erfolg (<code>without error</code> bzw. <code>with error</code>).\n</li><li><code>Shutdown</code>: Deinitialisierungs- bzw. Herunterfahraufruf.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Mit Eintritt des Ereignisses <code>Powerup</code> wechselt das System über die Transition <code>immediate</code> bedingungslos vom initialen Startknoten in den Zustand <code>PDUR_UNINIT</code>.\n</li><li>Im Zustand <code>PDUR_UNINIT</code> wird die Funktion <code>PduR_Init(ConfigPtr)</code> aufgerufen:\n<ul class=\"fig-list\"><li>Verläuft die Initialisierung fehlerfrei (<code>without error</code>), wechselt der PDU Router in den Zustand <code>PDUR_ONLINE</code>.\n</li><li>Schlägt die Initialisierung fehl bzw. tritt ein Fehler auf (<code>with error</code>), erfolgt der Übergang in den Zustand <code>PDUR_REDUCED</code>.\n</li></ul>\n</li><li>Jeder der drei Zustände (<code>PDUR_UNINIT</code>, <code>PDUR_ONLINE</code>, <code>PDUR_REDUCED</code>) besitzt einen direkten Übergang zum Endzustand <code>PowerDown</code>, der jeweils durch das Ereignis <code>Shutdown</code> ausgelöst wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Vorgabe für die Modulzustände des PDU Routers.\n</li><li>Der PduR darf Routingpfade nur im Zustand <code>PDUR_ONLINE</code> vollumfänglich bedienen.\n</li><li>Tritt bei der Initialisierung über <code>PduR_Init(ConfigPtr)</code> ein Fehler auf, muss die Zustandsmaschine deterministisch in <code>PDUR_REDUCED</code> verharren, bis ein <code>Shutdown</code> erfolgt.\n</li><li>Alle Zustände müssen einen sauberen Übergang bei Systemabschaltung (<code>Shutdown</code>) zum Zustand <code>PowerDown</code> gewährleisten.\n</li></ul>"}, {"id": "FIG-d69582a8b21dab35", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Lebenszyklus und der Betriebsmodi des AUTOSAR PDU Routers (PduR) innerhalb der Kommunikationsinfrastruktur der AUTOSAR Classic Platform (Services Layer).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Ruhezustand des Moduls vor erfolgreicher Konfiguration/Initialisierung.\n</li><li><code>PDUR_ONLINE</code>: Regulärer Betriebszustand für Routing- und Vermittlungsfunktionen von PDUs.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li><li>Endzustand (Final State): Kreis mit Diagonalkreuz (<code>PowerDown</code>).\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Ereignislose, unmittelbare Transition nach Systemstart.\n</li><li><code>PduR_Init(ConfigPtr) without error</code>: Initialisierungsaufruf mit Konfigurationszeiger bei fehlerfreier Ausführung.\n</li><li><code>Shutdown</code>: Deinitialisierungs- bzw. Herunterfahraufruf.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Mit Eintreten des Ereignisses <code>Powerup</code> geht das System über die Transition <code>immediate</code> unmittelbar vom Anfangszustand in den Zustand <code>PDUR_UNINIT</code> über.\n</li><li>Aus <code>PDUR_UNINIT</code> führt der fehlerfreie Aufruf von <code>PduR_Init(ConfigPtr) without error</code> in den Betriebszustand <code>PDUR_ONLINE</code>.\n</li><li>Sowohl aus <code>PDUR_UNINIT</code> als auch aus <code>PDUR_ONLINE</code> führt ein <code>Shutdown</code>-Ereignis direkt in den Endzustand <code>PowerDown</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Festlegung der Kernzustände des PDU Routers auf <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code>.\n</li><li>Ein fehlerhafter Initialisierungsaufruf führt nicht in einen reduzierten Betriebsmodus; der Zustand <code>PDUR_ONLINE</code> wird ausschließlich bei erfolgreicher Initialisierung (<code>without error</code>) erreicht.\n</li><li>Das Modul muss das Herunterfahren (<code>Shutdown</code>) aus den Zuständen <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code> in den Endzustand <code>PowerDown</code> unterstützen.\n</li></ul>"}, {"id": "FIG-761549807b2ad7a6", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR State Machine</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Services Layer der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Grundzustand vor Ausführung der Modulinitialisierung.\n</li><li><code>PDUR_ONLINE</code>: Betriebszustand für die Weiterleitung von Routing-Tabellen und I-PDUs.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Direkter, ereignisloser Übergang nach Modulstart.\n</li><li><code>PduR_Init(ConfigPtr) without error</code>: Modulinitialisierungsfunktion mit Konfigurationszeiger.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Systemereignis <code>Powerup</code> schaltet das Modul über die Transition <code>immediate</code> direkt vom Anfangsknoten in den Zustand <code>PDUR_UNINIT</code>.\n</li><li>Aus <code>PDUR_UNINIT</code> erfolgt bei erfolgreicher Initialisierung über <code>PduR_Init(ConfigPtr) without error</code> der Wechsel in den Betriebszustand <code>PDUR_ONLINE</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Reduzierung des formalen Zustandsmodells auf die Zustände <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code>.\n</li><li>Explizite Endzustände und Deinitialisierungsübergänge (<code>Shutdown</code>/<code>PowerDown</code>) sind im Diagramm nicht modelliert; das Modul verbleibt nach erfolgreicher Initialisierung im Zustand <code>PDUR_ONLINE</code>.\n</li><li>Routing-Dienste stehen erst nach erfolgreicher Durchführung von <code>PduR_Init</code> bereit.\n</li></ul>"}, {"id": "FIG-2cf9b920e8723db9", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR State Machine</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Services Layer der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Grundzustand vor Ausführung der Modulinitialisierung.\n</li><li><code>PDUR_ONLINE</code>: Betriebszustand für die Weiterleitung von Routing-Tabellen und I-PDUs.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Direkter, ereignisloser Übergang nach Modulstart.\n</li><li><code>PduR_Init(ConfigPtr) without error</code>: Modulinitialisierungsfunktion mit Konfigurationszeiger.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Systemereignis <code>Powerup</code> schaltet das Modul über die Transition <code>immediate</code> direkt vom Anfangsknoten in den Zustand <code>PDUR_UNINIT</code>.\n</li><li>Aus <code>PDUR_UNINIT</code> erfolgt bei erfolgreicher Initialisierung über <code>PduR_Init(ConfigPtr) without error</code> der Wechsel in den Betriebszustand <code>PDUR_ONLINE</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Reduzierung des formalen Zustandsmodells auf die Zustände <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code>.\n</li><li>Explizite Endzustände und Deinitialisierungsübergänge (<code>Shutdown</code>/<code>PowerDown</code>) sind im Diagramm nicht modelliert; das Modul verbleibt nach erfolgreicher Initialisierung im Zustand <code>PDUR_ONLINE</code>.\n</li><li>Routing-Dienste stehen erst nach erfolgreicher Durchführung von <code>PduR_Init</code> bereit.\n</li></ul>"}, {"id": "FIG-afaf2d423fffc9cf", "releases": ["R20-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR State Machine</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Services Layer der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Grundzustand vor Ausführung der Modulinitialisierung.\n</li><li><code>PDUR_ONLINE</code>: Betriebszustand für die Weiterleitung von Routing-Tabellen und I-PDUs.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Direkter, ereignisloser Übergang nach Modulstart.\n</li><li><code>PduR_Init(ConfigPtr) without error</code>: Modulinitialisierungsfunktion mit Konfigurationszeiger.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Systemereignis <code>Powerup</code> schaltet das Modul über die Transition <code>immediate</code> direkt vom Anfangsknoten in den Zustand <code>PDUR_UNINIT</code>.\n</li><li>Aus <code>PDUR_UNINIT</code> erfolgt bei erfolgreicher Initialisierung über <code>PduR_Init(ConfigPtr) without error</code> der Wechsel in den Betriebszustand <code>PDUR_ONLINE</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Reduzierung des formalen Zustandsmodells auf die Zustände <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code>.\n</li><li>Explizite Endzustände und Deinitialisierungsübergänge (<code>Shutdown</code>/<code>PowerDown</code>) sind im Diagramm nicht modelliert; das Modul verbleibt nach erfolgreicher Initialisierung im Zustand <code>PDUR_ONLINE</code>.\n</li><li>Routing-Dienste stehen erst nach erfolgreicher Durchführung von <code>PduR_Init</code> bereit.\n</li></ul>"}, {"id": "FIG-93f7f0d0fcc18158", "releases": ["R21-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR State Machine</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Services Layer der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Grundzustand vor Ausführung der Modulinitialisierung.\n</li><li><code>PDUR_ONLINE</code>: Betriebszustand für die Weiterleitung von Routing-Tabellen und I-PDUs.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Direkter, ereignisloser Übergang nach Modulstart.\n</li><li><code>PduR_Init(ConfigPtr) without error</code>: Modulinitialisierungsfunktion mit Konfigurationszeiger.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Systemereignis <code>Powerup</code> schaltet das Modul über die Transition <code>immediate</code> direkt vom Anfangsknoten in den Zustand <code>PDUR_UNINIT</code>.\n</li><li>Aus <code>PDUR_UNINIT</code> erfolgt bei erfolgreicher Initialisierung über <code>PduR_Init(ConfigPtr) without error</code> der Wechsel in den Betriebszustand <code>PDUR_ONLINE</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Reduzierung des formalen Zustandsmodells auf die Zustände <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code>.\n</li><li>Explizite Endzustände und Deinitialisierungsübergänge (<code>Shutdown</code>/<code>PowerDown</code>) sind im Diagramm nicht modelliert; das Modul verbleibt nach erfolgreicher Initialisierung im Zustand <code>PDUR_ONLINE</code>.\n</li><li>Routing-Dienste stehen erst nach erfolgreicher Durchführung von <code>PduR_Init</code> bereit.\n</li></ul>"}, {"id": "FIG-8ce4311af99fbd32", "releases": ["R22-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR State Machine</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Services Layer der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände:\n<ul class=\"fig-list\"><li><code>PDUR_UNINIT</code>: Initialer Grundzustand vor Ausführung der Modulinitialisierung.\n</li><li><code>PDUR_ONLINE</code>: Betriebszustand für die Weiterleitung von Routing-Tabellen und I-PDUs.\n</li></ul>\n</li><li>Pseudozustände:\n<ul class=\"fig-list\"><li>Anfangszustand (Initial State): Schwarzer Vollkreis mit Beschriftung <code>Powerup</code>.\n</li></ul>\n</li><li>Schnittstellen / Trigger:\n<ul class=\"fig-list\"><li><code>immediate</code>: Direkter, ereignisloser Übergang nach Modulstart.\n</li><li><code>PduR_Init(ConfigPtr) without error</code>: Modulinitialisierungsfunktion mit Konfigurationszeiger.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Systemereignis <code>Powerup</code> schaltet das Modul über die Transition <code>immediate</code> direkt vom Anfangsknoten in den Zustand <code>PDUR_UNINIT</code>.\n</li><li>Aus <code>PDUR_UNINIT</code> erfolgt bei erfolgreicher Initialisierung über <code>PduR_Init(ConfigPtr) without error</code> der Wechsel in den Betriebszustand <code>PDUR_ONLINE</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Reduzierung des formalen Zustandsmodells auf die Zustände <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code>.\n</li><li>Explizite Endzustände und Deinitialisierungsübergänge (<code>Shutdown</code>/<code>PowerDown</code>) sind im Diagramm nicht modelliert; das Modul verbleibt nach erfolgreicher Initialisierung im Zustand <code>PDUR_ONLINE</code>.\n</li><li>Routing-Dienste stehen erst nach erfolgreicher Durchführung von <code>PduR_Init</code> bereit.\n</li></ul>"}], "trans": [{"from": "FIG-238daf3685100864", "to": "FIG-d69582a8b21dab35", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zustand <code>PDUR_REDUCED</code>: Entfernt.\n</li><li>Transition von <code>PDUR_UNINIT</code> nach <code>PDUR_REDUCED</code> mit Trigger <code>PduR_Init(ConfigPtr) with error</code>: Entfernt.\n</li><li>Transition von <code>PDUR_REDUCED</code> nach <code>PowerDown</code> mit Trigger <code>Shutdown</code>: Entfernt.\n</li><li>Kopfzeile/Rahmen: UML-Frame-Kopf <code>stm PduR</code> und äußerer Rahmen entfernt.\n</li></ul>"}, {"from": "FIG-d69582a8b21dab35", "to": "FIG-761549807b2ad7a6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Endzustand <code>PowerDown</code>: Entfernt.\n</li><li>Transitionen mit Trigger <code>Shutdown</code> von <code>PDUR_UNINIT</code> und <code>PDUR_ONLINE</code> zum Endzustand <code>PowerDown</code>: Entfernt.\n</li><li>Kopfzeile/Rahmen: UML-Frame-Kopf mit Kennzeichnung <code>stm PduR State Machine</code> und äußerer Rahmen wieder eingefügt.\n</li></ul>"}, {"from": "FIG-761549807b2ad7a6", "to": "FIG-2cf9b920e8723db9", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2cf9b920e8723db9", "to": "FIG-afaf2d423fffc9cf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-afaf2d423fffc9cf", "to": "FIG-93f7f0d0fcc18158", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-93f7f0d0fcc18158", "to": "FIG-8ce4311af99fbd32", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8ce4311af99fbd32", "to": "FIG-afaf2d423fffc9cf", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-afaf2d423fffc9cf", "to": "FIG-8ce4311af99fbd32", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8ce4311af99fbd32", "to": "FIG-93f7f0d0fcc18158", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
